+// The audit trail: who changed what, and how it ended.
+
+/** Appends an entry (time `at`, key name, method, path, status) to the audit trail. */
+export function recordAudit(store, { at, by, method, path, status }) {
+  const entry = { id: store.nextId("audit"), at, by, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
