+// API keys and roles. A request carries `Authorization: Bearer <key>`; the key
+// names a role, and each route needs a role (viewer < cook < manager).
+import { AppError } from "../errors.js";
+
+const RANK = { viewer: 1, cook: 2, manager: 3 };
+
+// Besides reading, cooks may do exactly these.
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The API key record sent with the request, or an unauthorized AppError. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)$/i.exec(String(headers[name] ?? ""));
+  const found = m && store.data.apiKeys.find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** The least role that may make this request. */
+export function requiredRole(method, pathname) {
+  if (pathname === "/audit") return "manager";
+  if (method === "GET") return "viewer";
+  if (COOK_ROUTES.some(([m, re]) => m === method && re.test(pathname))) return "cook";
+  return "manager";
+}
+
+/** Throws forbidden unless `role` may make the request. */
+export function authorize(role, method, pathname) {
+  if ((RANK[role] ?? 0) < RANK[requiredRole(method, pathname)]) throw new AppError("forbidden", { role });
+}
